# ---------- Session state ----------
def init_state():
    defaults = {
        'screen': 'welcome',
        'landmark': None,
        'audio': None,
        'transcript': '',
        'evaluation': None,
        'observe_started_at': None,
        'record_requested': False,
        'record_started_at': None,
        'record_file': None,
        'record_stop_sent': False,
    }
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value

init_state()


def go(screen):
    st.session_state.screen = screen
    st.rerun()


def pick_landmark():
    st.session_state.landmark = random.choice(LANDMARKS)
    st.session_state.audio = None
    st.session_state.transcript = ''
    st.session_state.evaluation = None
    st.session_state.observe_started_at = None
    st.session_state.record_requested = False
    st.session_state.record_started_at = None
    st.session_state.record_file = None
    st.session_state.record_stop_sent = False


def evaluate_with_groq(text, landmark):
    client = Groq(api_key=GROQ_API_KEY)
    prompt = f'''أنت محكّم في لعبة المرشد السياحي "دلني". المتسابق رأى صورة لمعلم سعودي ولم يُعطَ اسمه.
المعلم الصحيح هو: {landmark['name']} في {landmark['location']}.
المعلومات المرجعية المسموح الاعتماد عليها: {landmark['facts']}

نص المتسابق:
{text}

قيّم الوصف بطريقة مرنة ومشجعة، ولا تكن نقديًا بزيادة. لا تعاقبه لأنه لم يذكر الاسم إذا كان وصفه يدل على المعلم. ولا تشترط نبذة تاريخية. إذا لم يذكر معيارًا، خفّض درجة ذلك المعيار فقط ولا تجعل النتيجة كلها صفرًا.
أعطِ درجات من 0 إلى 100 لكل معيار:
1 تعريف عن المعلم وموقعه
2 أبرز ما يميزه
3 صحة المعلومات ومدى توافقها مع المعلم
4 أفضل وقت للزيارة والفعاليات إن ذكرها المتسابق

احسب النتيجة النهائية من متوسط الدرجات الأربع.
أعد JSON فقط بهذا الشكل:
{{"score": 0, "criteria": {{"definition": 0, "features": 0, "accuracy": 0, "visit": 0}}, "feedback": "ملاحظات قصيرة بالعربية"}}
'''
    result = client.chat.completions.create(
        model='openai/gpt-oss-20b',
        messages=[
            {'role': 'system', 'content': 'أنت محكّم سياحي عادل ومشجع. أجب بالعربية وبـJSON فقط.'},
            {'role': 'user', 'content': prompt}
        ],
        temperature=0.35,
        max_completion_tokens=700,
        stream=False,
    )
    raw = result.choices[0].message.content or ''
    raw = raw.strip().replace('```json', '').replace('```', '').strip()
    return json.loads(raw)


def transcribe_audio(audio_bytes):
    client = Groq(api_key=GROQ_API_KEY)
    result = client.audio.transcriptions.create(
        file=('dalni.wav', audio_bytes),
        model='whisper-large-v3-turbo',
        language='ar',
        response_format='json',
        temperature=0.0,
    )
    return (result.text or '').strip()


# ---------- Welcome ----------
if st.session_state.screen == 'welcome':
    st.markdown('''
    <div class="welcome-panel">
      <div class="welcome-content">
        <div class="hero">
          <h1>كن مرشداً سياحياً</h1>
          <p>اكتشف جمال المملكة</p>
          <p>سيظهر لك معلم سياحي عشوائي من المملكة.<br>وقم بوصفه خلال 30 ثانية وكأنك مرشد سياحي.</p>
        </div>
      </div>
    </div>
    ''', unsafe_allow_html=True)
    st.markdown('<div class="card"><div class="guess">هل تستطيع التعرف على معالم المملكة من الصورة فقط؟</div></div>', unsafe_allow_html=True)
    if st.button('ابدأ التحدي', use_container_width=True, type='primary'):
        pick_landmark()
        go('observe')

# ---------- Observation: exactly 17 seconds ----------
elif st.session_state.screen == 'observe':
    lm = st.session_state.landmark
    if st.session_state.observe_started_at is None:
        st.session_state.observe_started_at = time.time()
    elapsed = time.time() - st.session_state.observe_started_at
    remaining = max(0, 17 - int(elapsed))
    st.markdown('<div class="hero"><h1>تعرّف على المعلم</h1><p>لاحظ الصورة جيدًا، ثم سننتقل تلقائيًا إلى مرحلة الشرح.</p></div>', unsafe_allow_html=True)
    st.image(lm['image'], use_container_width=True)
    st.markdown(f'<div class="timer">00:{remaining:02d}</div>', unsafe_allow_html=True)
    if remaining > 0:
        time.sleep(0.35)
        st.rerun()
    else:
        st.session_state.observe_started_at = None
        go('record')

# ---------- Recording: programmatic start + hard 30s stop ----------
elif st.session_state.screen == 'record':
    st.markdown('<div class="hero"><h1>أنت الآن مرشد سياحي</h1><p>تحدث بصوت واضح، لديك 30 ثانية.</p></div>', unsafe_allow_html=True)

    if not st.session_state.record_requested:
        st.markdown('<div class="record-hint">اضغط الزر الأزرق لبدء التسجيل، وسيبدأ العداد والميكروفون معًا.</div>', unsafe_allow_html=True)
        if st.button('ابدأ التسجيل', use_container_width=True, type='primary'):
            st.session_state.record_requested = True
            st.session_state.record_started_at = time.time()
            st.session_state.record_stop_sent = False
            st.session_state.record_file = os.path.join(
                tempfile.gettempdir(), f'dalni_{uuid.uuid4().hex}.wav'
            )
            st.rerun()
    else:
        elapsed = time.time() - st.session_state.record_started_at
        remaining = max(0, 30 - int(elapsed))
        should_stop = elapsed >= 30

        st.markdown(f'<div class="timer">00:{remaining:02d}</div>', unsafe_allow_html=True)
        st.markdown(
            '<div class="record-status">جارٍ التسجيل… سيتوقف تلقائيًا عند 00:00</div>' if not should_stop
            else '<div class="record-status">انتهت الـ30 ثانية — جارٍ إيقاف التسجيل وحفظه…</div>',
            unsafe_allow_html=True,
        )

        record_path = st.session_state.record_file

        def recorder_factory():
            return MediaRecorder(record_path)

        # The component is started/stopped by code, so there is no second Start/Stop button.
        ctx = webrtc_streamer(
            key='dalni_auto_recorder',
            mode=WebRtcMode.SENDONLY,
            desired_playing_state=not should_stop,
            media_stream_constraints={
                'video': False,
                'audio': {
                    'echoCancellation': True,
                    'noiseSuppression': True,
                    'autoGainControl': True,
                },
            },
            in_recorder_factory=recorder_factory,
            media_toggle_controls=False,
        )

        if should_stop:
            state = ctx.state
            playing = bool(getattr(state, 'playing', False))
            signalling = bool(getattr(state, 'signalling', False))
            file_ready = os.path.exists(record_path) and os.path.getsize(record_path) > 1000

            if not playing and not signalling and file_ready:
                with open(record_path, 'rb') as f:
                    st.session_state.audio = f.read()
                try:
                    os.remove(record_path)
                except OSError:
                    pass
                st.session_state.record_requested = False
                st.session_state.record_started_at = None
                st.session_state.record_file = None
                st.session_state.record_stop_sent = True
                st.session_state.screen = 'analyze'
                st.rerun()

        if st.session_state.record_requested:
            time.sleep(0.25)
            st.rerun()

# ---------- Analyze ----------
elif st.session_state.screen == 'analyze':
    st.markdown('<div class="hero"><h1>جاري تحليل وصفك</h1><p>يتم تحويل كلامك إلى نص داخليًا ثم يقيّمه الذكاء الاصطناعي.</p></div>', unsafe_allow_html=True)
    if not GROQ_API_KEY:
        st.error('لم يتم العثور على GROQ_API_KEY في ملف .env.')
        st.stop()
    if not st.session_state.audio:
        st.error('لم يصل التسجيل.')
        if st.button('إعادة التسجيل', use_container_width=True):
            pick_landmark()
            go('record')
        st.stop()
    try:
        with st.spinner('تحويل كلامك إلى نص...'):
            text = transcribe_audio(st.session_state.audio)
        st.session_state.transcript = text
        if not text:
            raise ValueError('لم يتم التقاط كلام واضح في التسجيل.')
        with st.spinner('تحليل الوصف وحساب النتيجة...'):
            evaluation = evaluate_with_groq(text, st.session_state.landmark)
        st.session_state.evaluation = evaluation
        go('result')
    except Exception as e:
        st.error(f'حدث خطأ أثناء التحليل: {e}')
        if st.button('المحاولة مرة أخرى', use_container_width=True):
            pick_landmark()
            go('observe')

# ---------- Result ----------
elif st.session_state.screen == 'result':
    lm = st.session_state.landmark
    ev = st.session_state.evaluation or {}
    score = max(0, min(100, int(ev.get('score', 0))))
    criteria = ev.get('criteria', {})
    feedback = ev.get('feedback', '')

    st.markdown('<div class="hero"><h1>نتيجة أدائك</h1></div>', unsafe_allow_html=True)
    st.image(lm['image'], use_container_width=True)
    st.markdown(f'<div class="timer">{score}%</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="guess">المعلم: {lm["name"]}</div>', unsafe_allow_html=True)

    labels = [
        ('definition', 'تعريف عن المعلم وموقعه'),
        ('features', 'أبرز ما يميزه'),
        ('accuracy', 'صحة المعلومات'),
        ('visit', 'أفضل وقت للزيارة والفعاليات'),
    ]
    for key, label in labels:
        value = max(0, min(100, int(criteria.get(key, 0))))
        st.progress(value / 100, text=f'{label}: {value}%')

    st.markdown('<div class="card">', unsafe_allow_html=True)
    st.markdown('**ملاحظات الذكاء الاصطناعي:**')
    st.write(feedback)
    st.markdown('</div>', unsafe_allow_html=True)

    if st.button('شاشة النهاية', use_container_width=True, type='primary'):
        go('end')

# ---------- End ----------
elif st.session_state.screen == 'end':
    st.markdown('''
    <div class="end-panel">
      <div class="end-content">
        <div class="hero">
          <h1>معًا نكتشف عالمًا اجمل</h1>
          <p>السياحة تصنع فرصًا اكثر وتبني مستقبلًا اكثر استدامه</p>
        </div>
      </div>
    </div>
    ''', unsafe_allow_html=True)
    if st.button('العودة إلى الشاشة الرئيسية', use_container_width=True, type='primary'):
        pick_landmark()
        st.session_state.screen = 'welcome'
        st.rerun()
